def q(v):
    return float(ZZ(round(v * n)) / n)


def probe(alpha, gamma, m=_sage_const_4 , seed=_sage_const_424242 ):
    alpha, gamma = q(alpha), q(gamma)
    if not (alpha + gamma + _sage_const_0p15 ) < _sage_const_1 :
        return ("infeasible_budget", None)
    if (n - alpha*n - gamma*n - _sage_const_0p15 *n) < _sage_const_4  or (n - alpha*n - gamma*n - _sage_const_0p1 *n) < _sage_const_4 :
        return ("no_headroom", None)
    gen = generate_gifp_instance(n, RR(alpha), RR(gamma), b1v, RR(_sage_const_0p15 ), seed, max_attempts=_sage_const_10 )
    if gen is None:
        return ("gen_none", None)
    N1_list, N2_list, share, ds = gen
    p1, q1, N1 = N1_list
    p2, q2, N2 = N2_list
    x0, y0, z0, w0 = ds

    pr = ZZ["x", "y", "z", "w"]
    x, y, z, w = pr.gens()
    f = x*z + _sage_const_2 **(int(_sage_const_0p15 *n) + int(gamma*n))*y*z + N2
    X = Integer(_sage_const_2  ** int(_sage_const_0p15 *n))
    Y = Integer(_sage_const_2  ** int(n - alpha*n - gamma*n - _sage_const_0p1 *n))
    Z = Integer(_sage_const_2  ** int(alpha*n))
    W = Integer(_sage_const_2  ** int(n - alpha*n))
    M = Integer(_sage_const_2  ** int(_sage_const_0p15 *n - _sage_const_0p1 *n))
    t = round((_sage_const_1  - sqrt(RR(alpha)))*m)
    s = round(sqrt(RR(alpha))*m)
    modular = M**m * N1**t
    if gcd(N2, modular) != _sage_const_1 :
        return ("noninvertible", None)
    N2inv = inverse_mod(N2, modular)
    qr = pr.quotient(z*w - N2)

    # The target row is the one that vanishes at the true root: take the shift
    # with highest f-power and evaluate the SCALED norm of the row that contains
    # the solution's monomial. A cheap faithful proxy: for EVERY shift, compute
    # the scaled coefficient vector's Euclidean norm and report the SMALLEST
    # norm among shifts -- the true solution must appear as a short combination.
    bounds = [X, Y, Z, W]
    shifts = []
    for ii in range(m+_sage_const_1 ):
        for jj in range(m-ii+_sage_const_1 ):
            g = (y*z)**jj * w**s * f**ii * M**(m-ii) * N1**max(t-ii, _sage_const_0 ) * N2inv**min(ii+jj, s)
            g = qr(g).lift()
            shifts.append(eliminate_N2(g, modular))

    monos = set()
    for sh in shifts:
        monos.update(sh.monomials())
    monos = sorted(monos)
    # scaled norm of each shift's coefficient row
    norms = []
    for sh in shifts:
        s2 = _sage_const_0 
        for m_ in monos:
            c = sh.monomial_coefficient(m_)
            if c:
                s2 += int((c * m_(*bounds))**_sage_const_2 )
        norms.append((s2.bit_length(), sh))
    norms.sort(key=lambda z: z[_sage_const_0 ])
    shortest_bits = norms[_sage_const_0 ][_sage_const_0 ]
    mod_bits = int(modular.nbits())
    # reconstruct_polynomials drops rows with norm^2 * w >= modulus^2, i.e.
    # norm ~ modular. Shortest must be well under.
    return ("ok", {"mod_bits": mod_bits, "shortest_shift_bits": shortest_bits,
                   "lattice_dim": (len(shifts), len(monos)),
                   "ratio_pct": round(_sage_const_100p0 *shortest_bits/mod_bits, _sage_const_1 )})


